mapper.sql:
where 1=1

		and crac_llave = #{llaveTabla}


		and crac_estado = #{estado}


		and crac_plantilla = #{plantilla}


		and brac_permisoscompletos = #{permisosCompletosFilter}


		and ((select upper(cdpl_nombre) from documentoplantilla_dplp where cdpl_llave = crac_plantilla) like upper('%' || #{filtroParametro} || '%'))
